#### 2. **Update JavaScript to reflect live frequency changes**

The Web Audio API doesn’t provide direct polling of frequency ramp values, so we'll simulate it by interpolating between `startFreq` and `stopFreq` in sync with time using `setInterval()`.

#### Replace your current `startSweep()` with:

```js
function startSweep() {
  let startFreq = Math.max(1, parseFloat(document.getElementById('startFreq').value));
  let stopFreq = Math.max(1, parseFloat(document.getElementById('stopFreq').value));
  let duration = parseFloat(document.getElementById('duration').value);
  let startVol = parseFloat(document.getElementById('startVol').value);
  let stopVol = parseFloat(document.getElementById('stopVol').value);

  if (osc) osc.stop();

  osc = ctx.createOscillator();
  gainNode = ctx.createGain();
  osc.type = 'sine';

  osc.connect(gainNode).connect(ctx.destination);
  osc.start();

  let now = ctx.currentTime;
  osc.frequency.setValueAtTime(startFreq, now);
  osc.frequency.linearRampToValueAtTime(stopFreq, now + duration);

  gainNode.gain.setValueAtTime(startVol, now);
  gainNode.gain.linearRampToValueAtTime(stopVol, now + duration);

  osc.stop(now + duration);

  // Update frequency display during sweep
  const display = document.getElementById('sweepFreqDisplay');
  const startTime = Date.now();
  const endTime = startTime + duration * 1000;
  const sweepRange = stopFreq - startFreq;

  const interval = setInterval(() => {
    const nowTime = Date.now();
    const elapsed = nowTime - startTime;
    if (nowTime >= endTime) {
      display.textContent = stopFreq.toFixed(1) + " Hz";
      clearInterval(interval);
      return;
    }
    const progress = elapsed / (duration * 1000);
    const currentFreq = startFreq + sweepRange * progress;
    display.textContent = currentFreq.toFixed(1) + " Hz";
  }, 30); // update ~33 times per second
}
```

